head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > displayHrMinSec]<br/>Calendar 컴포넌트의 시간 SelecBox 항목에 '시/분/초' 단위를 포함할지 설정합니다.",
    "validation" : [
        "미설정 시 기본값 false 로 동작하여 시간 SelectBox 아이템 목록에 단위 없이 숫자만 표시됩니다.",
        "true 설정 시 시간 SelectBox 의 아이템 목록에 '시', '분', '초' 단위를 포함합니다.",
        "true 설정 시 SelectBox 에 선택된 값에는 단위가 표시되지 않습니다.",
        "true 설정 시 설정된 언어에 따라 '시/분/초', 'h/m/s', '時/分/秒' 가 적용됩니다.",
        "calendarValueType='yearMonthDateHour', 'yearMonthDateTime', 'yearMonthDateTimeSec' 이고 renderType='component' 인 경우에만 동작합니다.",
        "calendarValueType 이 'yearMonthDateHour', 'yearMonthDateTime', 'yearMonthDateTimeSec' 가 아니면 시간 SelectBox 자체가 표시되지 않아 displayHrMinSec 가 동작하지 않습니다.",
        "renderType='native' 이면 displayHrMinSec 속성이 동작하지 않습니다.",
        "accessibility=true 이면 renderType 속성이 'native' 로 강제 설정되므로 displayHrMinSec 속성이 동작하지 않습니다.",
        "getValue() 메소드의 반환값에 단위는 포함되지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        displayHrMinSec : con_displayHrMinSec.getText(),
        calendarValueType : con_calendarValueType.getText(),
        renderType : con_renderType.getText(),
        accessibility : con_accessibility.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // 초기 선택일 설정 (calendarValueType 별 자릿수 맞춤)
    let cvt = target1.options.calendarValueType;
    let initVal = ({
        'yearMonthDate'       : '20250518',
        'yearMonth'           : '202505',
        'yearMonthDateHour'   : '2025051812',
        'yearMonthDateTime'   : '202505181234',
        'yearMonthDateTimeSec': '20250518123456'
    })[cvt] || '20250518';
    target1.gotoCalendar(initVal);
}



// calendar 클릭 시(시/분/초 SelectBox 포함) 시간 SelectBox 옵션 목록 + 선택값 자동 출력
scwin.target1_onclick = function (e) {
    setTimeout(function () {
        // validation: true 설정 시에도 선택된 값에는 단위 미표시 (sbRow 는 선택값만 표시)
        const sbRow = document.querySelector('div[id*=target1_selectbox_hour_itemTable]');
        wf_body_bottom.getObj("scwin").setReturnValue("[시간 SelectBox 선택값(단위 미포함)] '" + (sbRow ? sbRow.textContent : '(영역 없음)') + "'");

        // validation: getValue() 메소드의 반환값에 단위는 포함되지 않음
        wf_body_bottom.getObj("scwin").setReturnValue("[getValue() 반환값(단위 미포함)] '" + target1.getValue() + "'");
    }, 500);
};
